              case PM_BREAK_NODE: yyerror1(&loc, "Invalid break"); break;
              case PM_NEXT_NODE: yyerror1(&loc, "Invalid next"); break;
              case PM_REDO_NODE: yyerror1(&loc, "Invalid redo"); break;
